Section Walk.
  Variable L : heap_layout.
  Variable HI : heap_iface usegs L.
  Variables (MSF MDTBL SIGTBL : Z).
  Hypothesis HCALLOC : hl_calloc L = U_CALLOC.
  Hypothesis HFREE : hl_free L = U_FREE.
  Hypothesis HLS : 0 <= hl_stack L.
  Hypothesis HSIG : oid_lookup2_stmt usegs L U_OID_GET_SIG_ALG SIGTBL 560 64.
  Hypothesis HRSA : x509_get_rsassa_pss_params_stmt usegs L U_X509_GET_RSASSA_PSS_PARAMS MSF MDTBL.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
            (h : HST usegs L HI) (LB : list blk) (MD PK OPTS o0 lo : Z).
  Hypothesis SLO : lo <= bv_unsigned sp - 288 - hl_stack L.
  Hypothesis ACL : alloc_ceiling <= lo.
  Hypothesis ACP : 4096 < alloc_ceiling.
  Hypothesis SPA : bv_unsigned sp mod 16 = 0.
  Hypothesis SPR : 0 <= bv_unsigned sp < 2^64.
  Hypothesis HTOP : bv_unsigned sp <= heap_top usegs L HI h.

  Notation X := [(MD, MD + 4); (PK, PK + 4); (OPTS, OPTS + 8)].
  Notation POST := (x509_get_sig_alg_post usegs L HI ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h LB MD PK OPTS o0 lo m mo).
  Notation SPF := (Z_to_bv 64 (bv_unsigned sp + -48)).
